{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a patch of bare ground. Its body, head, and limbs are covered in dense, shaggy brown fur with lighter tan on the muzzle, chest and belly, resembling a bear in overall shape and proportion. Covering most of its back from the base of the neck to just above the rump is a large, domed, glossy dark brown shell with longitudinal ridges and a reflective surface, resembling a beetle's elytra. A single long, curved, glossy black horn projects upward and backward from the center of its forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with an elongated snout, black nose, small dark eyes, light tan fur on the muzzle and around the mouth, and thick brown fur on the cheeks and forehead",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn, sharply pointed at the tip, curving up and back with a small tooth-like projection on the inner curve near the middle",
      "where": "emerging from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in brown fur with slightly lighter inner edges",
      "where": "on top of the head on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred legs with dense dark brown fur on the outer sides and lighter brown-tan fur on the inner chest and belly, muscular in shape",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large paws with dark pads and long curved light-colored claws on each toe",
      "where": "at the bottom ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, furry brown tail, barely protruding",
      "where": "at the rear of the body just below the back edge of the large shell"
    },
    {
      "part": "shell",
      "looks_like": "large domed glossy dark brown beetle elytra with fine longitudinal striations, reflective highlights, a row of small oval holes along the lower margin, and a thin light rim where it meets the fur",
      "where": "covering the entire dorsal side from behind the shoulders to above the tail, overlying the fur"
    },
    {
      "part": "plates",
      "looks_like": "smaller glossy dark brown smooth plate with a curved, shield-like shape and reflective surface, like a beetle pronotum",
      "where": "on the neck/shoulder junction immediately in front of the main shell"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
